import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial, color, texture, mix } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Scene placement
  group.position.set(-3.2, 1, 0.06);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // Plane geometry (512:320 aspect ratio from atlas region)
  const planeWidth = 1.6;
  const planeHeight = 1.0;
  const geometry = new THREE.PlaneGeometry(planeWidth, planeHeight);

  // Load decorative image texture
  const imageTexture = ctx.textureLoader.load('/prism-mock/home/nodes/orb-decor.png');
  imageTexture.colorSpace = THREE.SRGBColorSpace;

  // Create engineered gradient surface with TSL nodes
  const paperColor = color(new THREE.Color(0xe8ecf2)); // paper
  const inkColor = color(new THREE.Color(0x16161d));   // ink

  // Subtle gradient overlay
  const gradientOverlay = mix(paperColor, inkColor, 0.12);

  // Composite: blend image with gradient for engineered effect
  const textureNode = texture(imageTexture);
  const finalColor = mix(textureNode, gradientOverlay, 0.18);

  // Material with engineered gradient surface
  const material = new MeshBasicNodeMaterial();
  material.colorNode = finalColor;

  // Create mesh
  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Render text content: "Pricing 1"
  if (ctx.fontAtlas) {
    const textContent = config.textContent?.[0] || 'Pricing 1';

    const textMesh = ctx.fontAtlas.createText({
      text: textContent,
      font: 'Lora',
      size: 0.39,
      weight: 400,
      color: 0x16161d,
      anchor: 'center'
    });

    textMesh.position.z = 0.01;
    group.add(textMesh);
  }

  // Resource cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    imageTexture.dispose();
  };

  // No event handlers for static composition
  group.userData.handlers = {};

  return group;
}
